<script setup>import{onMounted,ref}from'vue';import{api}from'../../api/http.js';import PageHeader from'../../components/common/PageHeader.vue';import T from'../../components/common/WorkspaceTable.vue';const rows=ref([]),suppliers=ref([]),error=ref(''),search=ref(''),form=ref({sku:'',name:'',category:'General',price:0,cost_price:0,stock_quantity:0,reorder_level:5,unit:'pc',supplier_id:null,status:'Active'});const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n||0);async function load(){try{const d=await api.get('/workspace/inventory',{search:search.value,per_page:100});rows.value=d.products.data;suppliers.value=d.suppliers}catch(x){error.value=x.message}}async function save(){try{await api.post('/workspace/products',form.value);form.value={sku:'',name:'',category:'General',price:0,cost_price:0,stock_quantity:0,reorder_level:5,unit:'pc',supplier_id:null,status:'Active'};await load()}catch(x){error.value=x.message}}async function adjust(row){const q=Number(prompt(`Adjustment for ${row.name} (negative to remove):`,0));if(!q)return;try{await api.post(`/workspace/products/${row.id}/adjust`,{quantity:q});await load()}catch(x){error.value=x.message}}onMounted(load)</script><template><PageHeader title="Inventory" description="Manage products and stock without leaving Vue."/><p v-if="error" class="form-error">{{error}}</p><form class="inline-form" @submit.prevent="save"><input v-model="form.sku" placeholder="SKU" required><input v-model="form.name" placeholder="Product name" required><input v-model.number="form.price" type="number" step=".01" placeholder="Price"><input v-model.number="form.cost_price" type="number" step=".01" placeholder="Cost"><input v-model.number="form.stock_quantity" type="number" placeholder="Stock"><button class="primary-button">Add product</button></form><div class="table-toolbar"><input v-model="search" placeholder="Search products"><button @click="load">Search</button></div><T :columns="[{key:'sku',label:'SKU'},{key:'name',label:'Product'},{key:'category',label:'Category'},{key:'price',label:'Price'},{key:'stock_quantity',label:'Stock'},{key:'reorder_level',label:'Reorder'}]" :rows="rows"><template #cell-price="{row}">{{money(row.price)}}</template><template #cell-stock_quantity="{row}"><span :class="{'danger-text':row.stock_quantity<=row.reorder_level}">{{row.stock_quantity}}</span></template><template #actions="{row}"><button @click="adjust(row)">Adjust stock</button></template></T></template>